"""English/Indonesian UI catalogue. Package names and external command logs stay intact."""
import locale
import os

_language = 'en'


def resolve_language(value='system'):
    if value in ('en', 'id'):
        return value
    value = os.environ.get('LANGUAGE') or os.environ.get('LC_ALL') or os.environ.get('LC_MESSAGES') or os.environ.get('LANG') or locale.getlocale()[0] or 'en'
    return 'id' if value.lower().split(':')[0].replace('-', '_').split('_')[0] in ('id', 'in') else 'en'


def configure(value='system'):
    global _language
    _language = resolve_language(value)
    return _language


def tr(text, **values):
    translated = ID.get(text, text) if _language == 'id' else text
    return translated.format(**values) if values else translated


